<?php $titulo_pagina='Meu Currículo';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarAutenticacao();if(($_SESSION['tipo_usuario']??'')==='empresa')redirecionar('/empresa/painel.php');$stmt=$mysqli->prepare('SELECT * FROM curriculos WHERE usuario_id=?');$stmt->bind_param('i',$_SESSION['usuario_id']);$stmt->execute();$cv=$stmt->get_result()->fetch_assoc();if($_SERVER['REQUEST_METHOD']==='POST'&&validar_csrf($_POST['csrf_token']??'')){$titulo=trim($_POST['titulo']??'');$resumo=trim($_POST['resumo']??'');$experiencia=trim($_POST['experiencia']??'');$formacao=trim($_POST['formacao']??'');$habilidades=trim($_POST['habilidades']??'');$cidade=trim($_POST['cidade']??'');$uf=mb_strtoupper(trim($_POST['uf']??''));$stmt=$mysqli->prepare('INSERT INTO curriculos(usuario_id,titulo,resumo,experiencia,formacao,habilidades,cidade,uf) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE titulo=VALUES(titulo),resumo=VALUES(resumo),experiencia=VALUES(experiencia),formacao=VALUES(formacao),habilidades=VALUES(habilidades),cidade=VALUES(cidade),uf=VALUES(uf)');$stmt->bind_param('isssssss',$_SESSION['usuario_id'],$titulo,$resumo,$experiencia,$formacao,$habilidades,$cidade,$uf);$stmt->execute();mensagem_sucesso('Currículo atualizado.');redirecionar('/dashboard/curriculo.php');}require_once __DIR__.'/../includes/header.php';?><div class="container"><div class="form-container"><h1>Meu Currículo</h1><?php exibir_mensagens(); ?><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><?php foreach(['titulo'=>'Objetivo profissional','resumo'=>'Resumo','experiencia'=>'Experiência','formacao'=>'Formação','habilidades'=>'Habilidades','cidade'=>'Cidade','uf'=>'UF'] as $campo=>$rotulo): ?><div class="form-group"><label><?php echo $rotulo; ?></label><?php if(in_array($campo,['resumo','experiencia','formacao','habilidades'])): ?><textarea name="<?php echo $campo; ?>" rows="4"><?php echo sanitizar($cv[$campo]??''); ?></textarea><?php else: ?><input name="<?php echo $campo; ?>" value="<?php echo sanitizar($cv[$campo]??''); ?>" required><?php endif; ?></div><?php endforeach; ?><button class="btn">Salvar currículo</button></form></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
